// Documentation is stored separately from conceptual objects and logical tables.
 QPointF notePosition(const DiagramNote &n)const{return logicalView?n.logical:uml?n.uml:n.chen;}
 QPointF &notePosition(DiagramNote &n){return logicalView?n.logical:uml?n.uml:n.chen;}
 QIcon noteIcon(){QPixmap pix(48,48);pix.setDevicePixelRatio(2);pix.fill(Qt::transparent);QPainter p(&pix);p.setRenderHint(QPainter::Antialiasing);p.setPen(QPen(theme.accent,1.6));p.setBrush(theme.surface);p.drawRect(QRectF(3,3,18,18));for(int y:{8,12,16})p.drawLine(7,y,17,y);return QIcon(pix);}
 bool noteEditor(DiagramNote &n){
  QDialog dialog(this);dialog.setObjectName("noteEditor");dialog.setWindowTitle(t("Modifica nota","Edit note"));QVBoxLayout layout(&dialog);
  QLabel hint(t("Scrivi qui una spiegazione del diagramma o la traccia di un esercizio. La stessa nota sarà leggibile nel concettuale e nel logico; il suo testo non cambia il modello.","Write an explanation of the diagram or an exercise here. The same note can be read in the conceptual and logical views; its text does not change the model."));hint.setWordWrap(true);layout.addWidget(&hint);
  QPlainTextEdit text;text.setObjectName("noteText");text.setPlainText(n.text);text.setAccessibleName(t("Testo della nota","Note text"));layout.addWidget(&text,1);
  QHBoxLayout sizes;QSpinBox width,height;width.setObjectName("noteWidth");height.setObjectName("noteHeight");width.setRange(160,2000);height.setRange(80,2000);width.setValue(qRound(n.size.width()));height.setValue(qRound(n.size.height()));sizes.addWidget(new QLabel(t("Larghezza","Width")));sizes.addWidget(&width);sizes.addWidget(new QLabel(t("Altezza","Height")));sizes.addWidget(&height);layout.addLayout(&sizes);
  QLabel count;layout.addWidget(&count);QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);layout.addWidget(&buttons);
  auto validate=[&]{auto length=text.toPlainText().size();count.setText(QString::number(length)+" / 10000");buttons.button(QDialogButtonBox::Ok)->setEnabled(length<=10000);};connect(&text,&QPlainTextEdit::textChanged,&dialog,validate);validate();
  connect(&buttons,&QDialogButtonBox::accepted,&dialog,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.resize(600,430);text.setFocus();
  if(dialog.exec()!=QDialog::Accepted)return false;
  n.text=text.toPlainText();n.size={double(width.value()),double(height.value())};return true;
 }
 void ensureNotesVisible(){if(!showNotes){showNotes=true;if(auto a=findChild<QAction*>("showNotes")){QSignalBlocker block(a);a->setChecked(true);}}}
 void addNoteAt(QPointF point){
  if(model.notes.size()>=500){status->setText(t("Limite di 500 note raggiunto.","The limit of 500 notes has been reached."));return;}
  DiagramNote n;n.id="note-"+newId();n.chen=n.uml=n.logical=point;if(!noteEditor(n))return;ensureNotesVisible();selection=n.id;selectionIds={n.id};change(t("Aggiungi nota","Add note"),[=](Model &m){m.notes<<n;});
 }
 void editNote(QString id){auto item=model.note(id);if(!item)return;auto edited=*item;const auto epoch=documentEpoch;if(!noteEditor(edited)||epoch!=documentEpoch)return;change(t("Modifica nota","Edit note"),[=](Model &m){if(auto n=m.note(id))*n=edited;});}
 void noteInspector(){auto n=model.note(selection);if(!n)return;QString id=n->id;note(t("NOTA","NOTE"));note(t("Doppio clic per modificare il testo. Trascina il riquadro per spostarlo, l’angolo inferiore destro per ridimensionarlo. Il testo rimane lo stesso nelle diverse viste, ma puoi collocare il riquadro dove ti è più comodo in ciascuna.","Double-click to edit the text. Drag the box to move it or the lower-right corner to resize it. The text stays the same across views, but you can place the box wherever it is most useful in each one."));auto edit=new QPushButton(t("Modifica testo e dimensioni…","Edit text and size…"));edit->setObjectName("editNote");form->addRow(edit);connect(edit,&QPushButton::clicked,this,[this,id]{editNote(id);});note(t("Le note possono essere incluse nel PDF. Non vengono trasferite al codice SQL.","Notes can be included in PDF. They are never transferred to SQL code."));}
 void renderNotes(){if(!showNotes)return;for(const auto &n:model.notes){auto node=new Node;node->kind="note";node->id=n.id;node->setData(0,n.id);node->label=n.text;node->size=n.size;node->theme=theme;node->setZValue(3);node->setToolTip(richTip(t("Nota · doppio clic per modificare. Trascina l’angolo inferiore destro per ridimensionare.\n","Note · double-click to edit. Drag the lower-right corner to resize.\n")+n.text.left(600)));scene->addItem(node);node->setPos(notePosition(n));nodes[n.id]=node;auto item=new QTreeWidgetItem(tree);item->setText(0,t("Nota: ","Note: ")+n.text.section('\n',0,0).left(70));item->setData(0,Qt::UserRole,n.id);}}
 void moveNotesDrag(QPointF delta){for(auto &n:model.notes)if(dragIds.contains(n.id)){notePosition(n)+=delta;if(auto node=nodes.value(n.id))node->setPos(notePosition(n));}}
 void resizeNoteDrag(QPointF delta){auto before=dragBefore.note(resizingNote);auto n=model.note(resizingNote);auto node=nodes.value(resizingNote);if(!before||!n||!node)return;QSizeF size(qBound(160.,before->size.width()+delta.x(),2000.),qBound(80.,before->size.height()+delta.y(),2000.));auto oldPos=notePosition(*before);*n=*before;n->size=size;notePosition(*n)=oldPos+QPointF((size.width()-before->size.width())/2,(size.height()-before->size.height())/2);node->setNoteSize(size);node->setPos(notePosition(*n));node->update();}
 void copyNote(){auto n=model.note(selection);if(!n)return;Model holder;holder.notes<<*n;auto mime=new QMimeData;mime->setData("application/x-dbschemastudio-note",QJsonDocument(holder.json()).toJson(QJsonDocument::Compact));mime->setText(n->text);QApplication::clipboard()->setMimeData(mime);}
 void pasteNoteAt(QPointF point){if(model.notes.size()>=500)return;auto mime=QApplication::clipboard()->mimeData();if(!mime)return;Model holder;QString error;if(!Model::parse(mime->data("application/x-dbschemastudio-note"),holder,error)||holder.notes.size()!=1)return;auto n=holder.notes.first();n.id="note-"+newId();n.chen=n.uml=n.logical=point;ensureNotesVisible();selection=n.id;selectionIds={n.id};change(t("Incolla nota","Paste note"),[=](Model &m){m.notes<<n;});}
 void pasteNoteAction(QMenu *menu,QPointF point){auto a=action(menu,t("Incolla nota","Paste note"),{},[this,point]{pasteNoteAt(point);});a->setObjectName("pasteNote");auto mime=QApplication::clipboard()->mimeData();a->setEnabled(mime&&mime->hasFormat("application/x-dbschemastudio-note"));}
 QMenu *noteContext(QPointF point){auto menu=new QMenu(this);if(selectionIds.size()==1){action(menu,t("Modifica nota…","Edit note…"),{},[this]{editNote(selection);});action(menu,t("Copia nota","Copy note"),{},[this]{copyNote();});}pasteNoteAction(menu,point);action(menu,t("Elimina selezione","Delete selection"),{},[this]{deleteSelected(true);});auto arrange=menu->addMenu(t("Disponi","Arrange"));addArrangementActions(arrange);return menu;}
